class TreeNode:
    def __init__(self, val: int):
        self.val = val
        self.left = None
        self.right = None


class Solution:
    def _is_mirror(
        self,
        left_node: TreeNode | None,
        right_node: TreeNode | None
    ) -> bool:
        if left_node is None and right_node is None:
            return True

        # One missing node means the mirrored structures differ.
        if left_node is None or right_node is None:
            return False

        if left_node.val != right_node.val:
            return False

        # Mirror comparison crosses left and right directions.
        return (
            self._is_mirror(
                left_node.left,
                right_node.right
            )
            and self._is_mirror(
                left_node.right,
                right_node.left
            )
        )

    def is_symmetric(self, root: TreeNode | None) -> bool:
        if root is None:
            return True

        return self._is_mirror(root.left, root.right)


if __name__ == "__main__":
    """
            1
           / \
          2   2
         /     \
        3       3
    """
    root = TreeNode(1)
    root.left = TreeNode(2)
    root.right = TreeNode(2)
    root.left.left = TreeNode(3)
    root.right.right = TreeNode(3)

    solution = Solution()

    print(solution.is_symmetric(root))
